import{_ as e,o as t,c as i,aj as s}from"./chunks/framework.C6uXqnaX.js";const u=JSON.parse('{"title":"Formatting data with pipes","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"tutorials/learn-angular/23-pipes-format-data.md","filePath":"tutorials/learn-angular/23-pipes-format-data.md"}'),p={name:"tutorials/learn-angular/23-pipes-format-data.md"};function n(o,a,r,l,h,d){return t(),i("div",null,a[0]||(a[0]=[s('<h1 id="formatting-data-with-pipes" tabindex="-1">Formatting data with pipes <a class="header-anchor" href="#formatting-data-with-pipes" aria-label="Permalink to &quot;Formatting data with pipes&quot;">​</a></h1><p>You can take your use of pipes even further by configuring them. Pipes can be configured by passing options to them.</p><div class="info custom-block"><p class="custom-block-title">NOTE</p><p>Learn more about <a href="/guide/templates/pipes">formatting data with pipes in the in-depth guide</a>.</p></div><p>In this activity, you will work with some pipes and pipe parameters.</p><hr><p>To pass parameters to a pipe, use the <code>:</code> syntax followed by the parameter value. Here&#39;s an example:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">template: `{{ date | date: &#39;medium&#39; }}`;</span></span></code></pre></div><p>The output is <code>Jun 15, 2015, 9:43:11 PM</code>.</p><p>Time to customize some pipe output:</p><h3 id="_1-format-a-number-with-decimalpipe" tabindex="-1">1. Format a number with <code>DecimalPipe</code> <a class="header-anchor" href="#_1-format-a-number-with-decimalpipe" aria-label="Permalink to &quot;1. Format a number with `DecimalPipe`&quot;">​</a></h3><p>In <code>app.ts</code>, update the template to include parameter for the <code>decimal</code> pipe.</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">template: ` ...</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">li</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Number with &quot;decimal&quot; {{ num | number: &#39;3.2-2&#39; }}&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">li</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">`</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">NOTE</p><p>What&#39;s that format? The parameter for the <code>DecimalPipe</code> is called <code>digitsInfo</code>, this parameter uses the format: <code>{minIntegerDigits}.{minFractionDigits}-{maxFractionDigits}</code></p></div><h3 id="_2-format-a-date-with-datepipe" tabindex="-1">2. Format a date with <code>DatePipe</code> <a class="header-anchor" href="#_2-format-a-date-with-datepipe" aria-label="Permalink to &quot;2. Format a date with `DatePipe`&quot;">​</a></h3><p>Now, update the template to use the <code>date</code> pipe.</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">template: ` ...</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">li</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Date with &quot;date&quot; {{ birthday | date: &#39;medium&#39; }}&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">li</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">`</span></span></code></pre></div><p>For extra fun, try some different parameters for <code>date</code>. More information can be found in the <a href="/guide/templates/pipes">Angular docs</a>.</p><h3 id="_3-format-a-currency-with-currencypipe" tabindex="-1">3. Format a currency with <code>CurrencyPipe</code> <a class="header-anchor" href="#_3-format-a-currency-with-currencypipe" aria-label="Permalink to &quot;3. Format a currency with `CurrencyPipe`&quot;">​</a></h3><p>For your last task, update the template to use the <code>currency</code> pipe.</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">template: ` ...</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">li</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Currency with &quot;currency&quot; {{ cost | currency }}&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">li</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">`</span></span></code></pre></div><p>You can also try different parameters for <code>currency</code>. More information can be found in the <a href="/guide/templates/pipes">Angular docs</a>.</p><p>Great work with pipes. You&#39;ve made some great progress so far.</p><p>There are even more built-in pipes that you can use in your applications. You can find the list in the <a href="/guide/templates/pipes">Angular documentation</a>.</p><p>In the case that the built-in pipes don&#39;t cover your needs, you can also create a custom pipe. Check out the next lesson to find out more.</p>',24)]))}const m=e(p,[["render",n]]);export{u as __pageData,m as default};
